import{_ as s,o as n,c as e,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"81. C 标准时间线（C89 到 C23）","description":"The Little Book of C 中文版 — 81. C 标准时间线（C89 到 C23）","frontmatter":{"title":"81. C 标准时间线（C89 到 C23）","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","09-可移植与现代 C","中文"],"description":"The Little Book of C 中文版 — 81. C 标准时间线（C89 到 C23）","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":81,"sidebarWeight":81,"alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/081-The C Standard Timeline (C89 to C23)","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/081-The C Standard Timeline (C89 to C23)"},"headers":[],"relativePath":"posts/c教程/zh-CN/09-可移植与现代 C/081-The C Standard Timeline (C89 to C23).md","filePath":"posts/c教程/zh-CN/09-可移植与现代 C/081-The C Standard Timeline (C89 to C23).md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/09-可移植与现代 C/081-The C Standard Timeline (C89 to C23).md"};function l(t,a,o,c,d,r){return n(),e("div",null,[...a[0]||(a[0]=[i(`<p>[English version](/posts/c教程/en-US/09-Portable and Modern C/081-The C Standard Timeline (C89 to C23))</p><p>C 语言已经存在了五十多年了，它的发展是缓慢而谨慎的。 C 标准的每个版本都改进了语言，同时保持与数十年现有代码的向后兼容性。</p><p>了解 C 标准的时间表有助于您编写可移植的现代代码，并了解哪些功能可以在目标环境中安全使用。</p><h4 id="步骤-1-开始-k-r-c-1972–1989" tabindex="-1">步骤 1. 开始，K&amp;R C (1972–1989) <a class="header-anchor" href="#步骤-1-开始-k-r-c-1972–1989" aria-label="Permalink to &quot;步骤 1. 开始，K&amp;R C (1972–1989)&quot;">​</a></h4><p>C 诞生于 20 世纪 70 年代初的贝尔实验室，由 Dennis Ritchie 开发，作为 Unix 的系统编程语言。第一本书《C 编程语言》（Kernighan 和 Ritchie，1978 年）非正式地定义了“K&amp;R C”。</p><p>主要特征：</p><ul><li>尚未标准化。</li><li>隐式函数声明。</li><li>不<code>void</code>不带返回值的函数的类型。</li><li>无函数原型（未对参数进行类型检查）。</li><li>头文件是可选的。</li></ul><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main() {</span></span>
<span class="line"><span>    printf(&quot;Hello, world\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>虽然简单、直接、危险，但确实有效。</p><h4 id="步骤-2-ansi-c-c89-c90" tabindex="-1">步骤 2. ANSI C (C89 / C90) <a class="header-anchor" href="#步骤-2-ansi-c-c89-c90" aria-label="Permalink to &quot;步骤 2. ANSI C (C89 / C90)&quot;">​</a></h4><p>1989 年，C 被 ANSI 标准化（1990 年被 ISO 标准化）。这个版本 C89/C90 统一了编译器行为，并使 C 可以跨系统移植。</p><p>主要特点：</p><ul><li>函数原型（<code>int add(int, int);</code>)</li><li>标准标头（<code>&lt;stdio.h&gt;</code>,<code>&lt;stdlib.h&gt;</code>,<code>&lt;string.h&gt;</code>) -<code>void</code>关键词</li><li>类型限定符：<code>const</code>,<code>volatile</code></li><li>新的库函数（<code>memcpy</code>,<code>qsort</code>,<code>assert</code>)</li><li>正式化标准库</li><li>仍然不支持单行注释（使用<code>/* */</code>)</li></ul><p>小代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add(2, 3));</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="步骤-3-c95-iso-修订版" tabindex="-1">步骤 3.C95（ISO 修订版） <a class="header-anchor" href="#步骤-3-c95-iso-修订版" aria-label="Permalink to &quot;步骤 3.C95（ISO 修订版）&quot;">​</a></h4><p>改进 C90 的一个小更新，很少被提及，但仍然很重要。</p><p>额外：</p><ul><li>宽字符支持（<code>&lt;wchar.h&gt;</code>)</li><li>多字节字符串</li><li>更多国际化实用程序</li><li>像这样的宏<code>__STDC_VERSION__</code></li></ul><p>它为以后版本中的 Unicode 支持铺平了道路。</p><h4 id="步骤-4-c99-现代化开始" tabindex="-1">步骤 4. C99，现代化开始 <a class="header-anchor" href="#步骤-4-c99-现代化开始" aria-label="Permalink to &quot;步骤 4. C99，现代化开始&quot;">​</a></h4><p>C99（1999 年发布）是自诞生以来最大的更新。</p><p>主要改进：</p><p>-<code>//</code>单行注释</p><ul><li>任何地方的变量声明</li><li>内联函数 -<code>long long</code>（64 位整数） -<code>stdbool.h</code>为了<code>bool</code>,<code>true</code>,<code>false</code> -<code>stdint.h</code>对于固定宽度整数 (<code>int32_t</code>,<code>uint64_t</code>)</li><li>指定的初始值设定项和复合文字</li><li>灵活的数组成员 -<code>snprintf</code>更安全的字符串格式</li><li>可变长度数组（VLA）</li></ul><p>小代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdbool.h&gt;</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    bool done = false;</span></span>
<span class="line"><span>    uint64_t sum = 0;</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 5; i++)</span></span>
<span class="line"><span>        sum += i;</span></span>
<span class="line"><span>    printf(&quot;%llu\\n&quot;, (unsigned long long)sum);</span></span>
<span class="line"><span>    return done;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>C99 引入了更安全、更具表现力的语法，让 C 感觉很现代。</p><h4 id="步骤-5-c11-并发性和安全性" tabindex="-1">步骤 5.C11，并发性和安全性 <a class="header-anchor" href="#步骤-5-c11-并发性和安全性" aria-label="Permalink to &quot;步骤 5.C11，并发性和安全性&quot;">​</a></h4><p>C11 于 2011 年发布，添加了更好的线程和安全机制。</p><p>关键补充：</p><p>-<code>_Thread_local</code>存储说明符 -<code>&lt;threads.h&gt;</code>用于可移植线程、互斥体、条件变量 -<code>_Atomic</code>对于原子操作 -<code>_Static_assert</code>用于编译时检查</p><ul><li>边界检查函数（<code>strcpy_s</code>,<code>memcpy_s</code>)</li><li>可选附件 K 更安全的标准库函数</li><li>改进了 Unicode 和宽字符支持</li></ul><p>小代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;threads.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int run(void *arg) {</span></span>
<span class="line"><span>    printf(&quot;Hello from thread %d\\n&quot;, *(int *)arg);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int id = 1;</span></span>
<span class="line"><span>    thrd_t t;</span></span>
<span class="line"><span>    thrd_create(&amp;t, run, &amp;id);</span></span>
<span class="line"><span>    thrd_join(t, NULL);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>C11 使 C 更安全并且具有并发意识，尽管并非所有编译器都实现了<code>&lt;threads.h&gt;</code>完全。</p><h4 id="步骤-6-c17-又名-c18-改进" tabindex="-1">步骤 6. C17（又名 C18），改进 <a class="header-anchor" href="#步骤-6-c17-又名-c18-改进" aria-label="Permalink to &quot;步骤 6. C17（又名 C18），改进&quot;">​</a></h4><p>C17 正式通过 ISO/IEC 9899:2018（2018 年发布），修复了 C11 中的不一致和错误，但没有添加新功能。</p><p>亮点：</p><ul><li>对原子、宏和 UB 规则的澄清。</li><li>改进了与 C++ 编译器的兼容性。</li><li>标准库中的错误修复。 -<code>__STDC_VERSION__</code>是<code>201710L</code>.</li></ul><p>它是现代 C 代码库的默认“稳定”标准。</p><h4 id="步骤-7-c23-最新标准" tabindex="-1">步骤 7. C23，最新标准 <a class="header-anchor" href="#步骤-7-c23-最新标准" aria-label="Permalink to &quot;步骤 7. C23，最新标准&quot;">​</a></h4><p>C23 是最新的（于 2024 年发布），在不破坏向后兼容性的情况下继续现代化。</p><p>主要特点：</p><p>-<code>typeof</code>（就像在海湾合作委员会） -<code>nullptr</code>关键词 -<code>static_assert</code>（别名为<code>_Static_assert</code>)</p><ul><li>UTF-8 字符串文字：<code>u8&quot;Hello&quot;</code></li><li>新的标准属性（<code>[[maybe_unused]]</code>,<code>[[nodiscard]]</code>) -<code>constexpr</code>类似特征（<code>constexpr</code>功能已规划）</li><li>更好的 Unicode 和格式化 API</li><li>更安全的库扩展</li><li>改进了与 C++ 的互操作性</li></ul><p>小代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x = 10;</span></span>
<span class="line"><span>    [[maybe_unused]] int y = 20;</span></span>
<span class="line"><span>    static_assert(sizeof(int) == 4, &quot;Expected 4-byte int&quot;);</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, x);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>C23 使 C 更接近现代 C++ 和 Rust 风格的安全性，同时保持简单和轻量级。</p><h4 id="步骤-8-检查编译器的版本" tabindex="-1">步骤 8. 检查编译器的版本 <a class="header-anchor" href="#步骤-8-检查编译器的版本" aria-label="Permalink to &quot;步骤 8. 检查编译器的版本&quot;">​</a></h4><p>您可以使用以下命令检查编译器支持的 C 标准：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -dM -E - &lt; /dev/null | grep __STDC_VERSION__</span></span></code></pre></div><p>常见输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>199901L  → C99  </span></span>
<span class="line"><span>201112L  → C11  </span></span>
<span class="line"><span>201710L  → C17  </span></span>
<span class="line"><span>202311L  → C23</span></span></code></pre></div><p>或者编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -std=c99 program.c</span></span>
<span class="line"><span>gcc -std=c11 program.c</span></span>
<span class="line"><span>gcc -std=c23 program.c</span></span></code></pre></div><h4 id="步骤-9-兼容性和可移植性提示" tabindex="-1">步骤 9. 兼容性和可移植性提示 <a class="header-anchor" href="#步骤-9-兼容性和可移植性提示" aria-label="Permalink to &quot;步骤 9. 兼容性和可移植性提示&quot;">​</a></h4><ul><li>始终明确声明标准：<code>-std=c11</code>或者<code>-std=c17</code>.</li><li>避免特定于编译器的扩展，除非用<code>#ifdef __GNUC__</code>.</li><li>使用标准标题，例如<code>&lt;stdint.h&gt;</code>和<code>&lt;stdbool.h&gt;</code>.</li><li>编写库时，优先选择支持您的需求的最低标准。</li><li>添加<code>_Static_assert</code>或者<code>#error</code>对于不受支持的标准。</li></ul><h4 id="步骤-10-小代码-版本检测器" tabindex="-1">步骤 10. 小代码：版本检测器 <a class="header-anchor" href="#步骤-10-小代码-版本检测器" aria-label="Permalink to &quot;步骤 10. 小代码：版本检测器&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>#if __STDC_VERSION__ &gt;= 202311L</span></span>
<span class="line"><span>    printf(&quot;C23 or newer\\n&quot;);</span></span>
<span class="line"><span>#elif __STDC_VERSION__ &gt;= 201710L</span></span>
<span class="line"><span>    printf(&quot;C17\\n&quot;);</span></span>
<span class="line"><span>#elif __STDC_VERSION__ &gt;= 201112L</span></span>
<span class="line"><span>    printf(&quot;C11\\n&quot;);</span></span>
<span class="line"><span>#elif __STDC_VERSION__ &gt;= 199901L</span></span>
<span class="line"><span>    printf(&quot;C99\\n&quot;);</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    printf(&quot;C90 or earlier\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行以查看您的编译器支持什么。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>C 的演变显示了其独特的哲学：缓慢变化，但绝不破坏旧代码。了解您的目标标准意味着您可以自信地使用现代功能，而不会失去可移植性。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写上面的版本检测程序并运行它<code>-std=c99</code>,<code>-std=c11</code>， 和<code>-std=c23</code>.</li><li>尝试<code>_Static_assert</code>和<code>_Thread_local</code>，查看哪些标准支持它们。</li><li>尝试使用以下命令编译一个小线程示例<code>&lt;threads.h&gt;</code>.</li><li>查看编译器的文档，了解实现了哪些 C23 功能。</li><li>选择一项功能（例如<code>[[nodiscard]]</code>）并在一个小项目中使用它。</li></ol><p>接下来，您将探索可移植性和字节顺序，这些不可见的细节决定了 C 程序在不同机器和体系结构上的行为方式。</p>`,67)])])}const C=s(p,[["render",l]]);export{u as __pageData,C as default};
